exec(compile('#!/usr/bin/env python3\n"""Derive conservative gate-composition summaries from the v3 CSV (stdlib only)."""\n\nfrom __future__ import annotations\n\nimport argparse\nimport csv\nimport hashlib\nimport json\nimport math\nfrom collections import Counter\nfrom pathlib import Path\n\n\nROOT = Path(__file__).resolve().parents[3]\nDEFAULT_INPUT = ROOT / "data_first" / "feature_v3" / "circuit_features_v3.csv"\nDEFAULT_OUTPUT = Path(__file__).resolve().parent\n\n# Literal mapping from canonical gate category to v3 source count columns.\n# QASM gate names are case-sensitive; this project explicitly treats legacy\n# uppercase U and lowercase u as aliases for this composition inventory.\nCANONICAL_GATE_SOURCES = {\n    "ccx": ("gate_ccx",), "ch": ("gate_ch",), "cp": ("gate_cp",),\n    "crx": ("gate_crx",), "cry": ("gate_cry",), "crz": ("gate_crz",),\n    "cswap": ("gate_cswap",), "cu": ("gate_cu",), "cu1": ("gate_cu1",),\n    "cx": ("gate_cx",), "cy": ("gate_cy",), "cz": ("gate_cz",),\n    "h": ("gate_h",), "p": ("gate_p",), "rx": ("gate_rx",),\n    "rxx": ("gate_rxx",), "ry": ("gate_ry",), "rz": ("gate_rz",),\n    "rzz": ("gate_rzz",), "s": ("gate_s",), "sdg": ("gate_sdg",),\n    "swap": ("gate_swap",), "sx": ("gate_sx",), "sxdg": ("gate_sxdg",),\n    "t": ("gate_t",), "tdg": ("gate_tdg",), "u": ("gate_U", "gate_u"),\n    "u1": ("gate_u1",), "u2": ("gate_u2",), "u3": ("gate_u3",),\n    "x": ("gate_x",), "y": ("gate_y",), "z": ("gate_z",),\n}\n\n# These groups are intentionally overlapping name-based summaries. They make\n# no claim about parameter values or the circuit\'s actual compiled unitaries.\nFAMILIES = {\n    "diagonal": ("cp", "crz", "cz", "p", "rzz", "s", "sdg", "t", "tdg", "u1", "z"),\n    "rotation": ("crx", "cry", "crz", "cu", "cu1", "p", "rx", "rxx", "ry", "rz", "rzz", "u", "u1", "u2", "u3"),\n    # Only named, fixed Clifford gates included: CX, CZ, H, S/Sdg, SX/SXdg,\n    # Pauli X/Y/Z, and SWAP. Parameter-dependent families are excluded.\n    "fixed_clifford": ("cx", "cz", "h", "s", "sdg", "swap", "sx", "sxdg", "x", "y", "z"),\n    "t_family": ("t", "tdg"),\n}\n\nPROPORTION_COLUMNS = [f"gate_prop_{name}" for name in CANONICAL_GATE_SOURCES]\nFEATURE_COLUMNS = [\n    *PROPORTION_COLUMNS,\n    "gate_type_diversity", "gate_type_entropy", "gate_type_entropy_norm",\n    "oneq_count",\n    *(f"{family}_count" for family in FAMILIES),\n    *(f"{family}_fraction" for family in FAMILIES),\n    "gate_depth_per_qubit", "gate_depth_per_unitary",\n]\nOUTPUT_COLUMNS = ["filename", *FEATURE_COLUMNS]\n\n\ndef _bool(value: str) -> bool:\n    return value.strip().lower() == "true"\n\n\ndef _number(row: dict[str, str], column: str) -> float | None:\n    raw = row.get(column, "")\n    return None if raw is None or raw.strip() == "" else float(raw)\n\n\ndef _int_exact(row: dict[str, str], column: str) -> int:\n    value = _number(row, column)\n    if value is None or not value.is_integer() or value < 0:\n        raise ValueError(f"exact row has invalid nonnegative integer {column}: {value}")\n    return int(value)\n\n\ndef derive(row: dict[str, str]) -> dict[str, float | int | str | None]:\n    out: dict[str, float | int | str | None] = {"filename": row["filename"]}\n    count_exact = _bool(row.get("counts_exact", ""))\n    depth_exact = _bool(row.get("depth_exact", ""))\n\n    # Count-derived features are unavailable unless the source explicitly\n    # qualifies its expanded primitive counts. This preserves null vs zero.\n    if count_exact:\n        source_counts: dict[str, int] = {}\n        for canonical, source_columns in CANONICAL_GATE_SOURCES.items():\n            # A known source column absent from an older compatible table is\n            # an absent gate (zero) only on count-exact rows.\n            source_counts[canonical] = sum(\n                _int_exact(row, col) if row.get(col, "").strip() else 0\n                for col in source_columns\n            )\n        unitary = _int_exact(row, "unitary_count")\n        if sum(source_counts.values()) != unitary:\n            raise ValueError(\n                f"{row[\'filename\']}: canonical primitive gate sum "\n                f"{sum(source_counts.values())} != unitary_count {unitary}"\n            )\n        for name, count in source_counts.items():\n            out[f"gate_prop_{name}"] = count / unitary if unitary else None\n        nonzero = [c for c in source_counts.values() if c > 0]\n        out["gate_type_diversity"] = sum(c > 0 for c in source_counts.values())\n        entropy = -sum((c / unitary) * math.log(c / unitary)\n                       for c in nonzero) if unitary else None\n        out["gate_type_entropy"] = entropy\n        n_types = len(CANONICAL_GATE_SOURCES)\n        out["gate_type_entropy_norm"] = (\n            entropy / math.log(n_types) if entropy is not None and unitary and n_types > 1 else None\n        )\n        twoq = _int_exact(row, "twoq_count")\n        multiq = _int_exact(row, "multiq_count")\n        oneq = unitary - twoq - multiq\n        if oneq < 0:\n            raise ValueError(f"{row[\'filename\']}: negative derived oneq_count {oneq}")\n        out["oneq_count"] = oneq\n        for family, members in FAMILIES.items():\n            count = sum(source_counts[name] for name in members)\n            out[f"{family}_count"] = count\n            out[f"{family}_fraction"] = count / unitary if unitary else None\n    else:\n        for col in PROPORTION_COLUMNS + ["gate_type_diversity", "gate_type_entropy",\n                                          "gate_type_entropy_norm", "oneq_count"]:\n            out[col] = None\n        for family in FAMILIES:\n            out[f"{family}_count"] = None\n            out[f"{family}_fraction"] = None\n\n    # Schedule features have their own qualification flag. Zero denominators\n    # are undefined ratios, represented as null, never imputed to zero.\n    if depth_exact:\n        depth = _number(row, "gate_depth")\n        n_qubits = _number(row, "n_qubits")\n        unitary = _number(row, "unitary_count") if count_exact else None\n        out["gate_depth_per_qubit"] = depth / n_qubits if depth is not None and n_qubits and n_qubits > 0 else None\n        out["gate_depth_per_unitary"] = depth / unitary if depth is not None and unitary and unitary > 0 else None\n    else:\n        out["gate_depth_per_qubit"] = None\n        out["gate_depth_per_unitary"] = None\n    return out\n\n\ndef dictionary_rows() -> list[dict[str, str]]:\n    rows: list[dict[str, str]] = []\n    for name in CANONICAL_GATE_SOURCES:\n        alias_note = " gate_U and gate_u are summed as one case-alias category." if name == "u" else ""\n        rows.append({\n            "column": f"gate_prop_{name}", "family": "normalized gate composition",\n            "meaning": f"Expanded count for canonical primitive gate name {name} divided by unitary_count.",\n            "units": "proportion", "availability": "Derived from v3 primitive counts when counts_exact=True",\n            "required_exactness_flag": "counts_exact", "zero_null_policy": "0 for an absent gate in an exact row; null when counts are inexact or unitary_count is zero.",\n            "caveat": "Name-based composition of expanded built-in QASM operations; not compiled/native gate mix." + alias_note,\n            "model_role": "predictor_candidate",\n        })\n    rows.extend([\n        {"column": "gate_type_diversity", "family": "gate composition diversity", "meaning": "Number of canonical gate names with positive expanded count.", "units": "gate types", "availability": "Derived when counts_exact=True", "required_exactness_flag": "counts_exact", "zero_null_policy": "0 for an exact zero-operation circuit; null when inexact.", "caveat": "Counts canonical categories; U/u are merged.", "model_role": "predictor_candidate"},\n        {"column": "gate_type_entropy", "family": "gate composition diversity", "meaning": "Shannon entropy -sum(p_g ln p_g) over positive canonical gate-type proportions.", "units": "nats", "availability": "Derived when counts_exact=True", "required_exactness_flag": "counts_exact", "zero_null_policy": "null for zero-operation circuits or inexact counts.", "caveat": "Gate-type entropy is distinct from graph degree-mass entropy.", "model_role": "predictor_candidate"},\n        {"column": "gate_type_entropy_norm", "family": "gate composition diversity", "meaning": "Gate-type Shannon entropy divided by ln(33), the maximum for this fixed vocabulary.", "units": "fraction of vocabulary maximum", "availability": "Derived when counts_exact=True", "required_exactness_flag": "counts_exact", "zero_null_policy": "null for zero-operation circuits or inexact counts.", "caveat": "Vocabulary-normalized entropy, not normalized by observed diversity.", "model_role": "predictor_candidate"},\n        {"column": "oneq_count", "family": "operation arity", "meaning": "unitary_count - twoq_count - multiq_count.", "units": "unitary operations", "availability": "Derived when counts_exact=True", "required_exactness_flag": "counts_exact", "zero_null_policy": "0 is valid for exact rows; null when counts are inexact.", "caveat": "Remainder under v3 arity definitions.", "model_role": "predictor_candidate"},\n    ])\n    family_caveats = {\n        "diagonal": "Conservative name list: cp, crz, cz, p, rzz, s, sdg, t, tdg, u1, z.",\n        "rotation": "Parameterized-name bucket: crx, cry, crz, cu, cu1, p, rx, rxx, ry, rz, rzz, u, u1, u2, u3; no physical rotation claim.",\n        "fixed_clifford": "Only fixed named Cliffords: cx, cz, h, s, sdg, swap, sx, sxdg, x, y, z. Excludes parameterized gates and ambiguous controlled gates.",\n        "t_family": "Named T and T-dagger counts only.",\n    }\n    for family, members in FAMILIES.items():\n        for suffix, units, meaning in (\n            ("count", "gate instances", f"Sum of expanded canonical counts in {family}: {\', \'.join(members)}."),\n            ("fraction", "fraction of unitary_count", f"{family}_count divided by unitary_count."),\n        ):\n            rows.append({"column": f"{family}_{suffix}", "family": f"overlapping name family: {family}", "meaning": meaning,\n                         "units": units, "availability": "Derived when counts_exact=True", "required_exactness_flag": "counts_exact",\n                         "zero_null_policy": "0 for an exact row with no matching gates; null when counts are inexact; fractions null at zero unitary_count.",\n                         "caveat": family_caveats[family] + " Family definitions intentionally overlap.", "model_role": "predictor_candidate"})\n    for col, meaning, denominator in (\n        ("gate_depth_per_qubit", "gate_depth divided by n_qubits.", "positive n_qubits"),\n        ("gate_depth_per_unitary", "gate_depth divided by unitary_count.", "positive unitary_count and counts_exact"),\n    ):\n        rows.append({"column": col, "family": "qualified depth density", "meaning": meaning, "units": "depth layers per " + ("qubit" if col.endswith("qubit") else "unitary operation"),\n                     "availability": "Derived when depth_exact=True", "required_exactness_flag": "depth_exact" + (" and counts_exact" if col.endswith("unitary") else ""),\n                     "zero_null_policy": f"Null if {denominator} is unavailable or zero; null when depth_exact=False.",\n                     "caveat": "A compact descriptive ratio; not a simulator cost model.", "model_role": "predictor_candidate"})\n    return rows\n\n\ndef main() -> None:\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument("--input", type=Path, default=DEFAULT_INPUT)\n    parser.add_argument("--output-dir", type=Path, default=DEFAULT_OUTPUT)\n    args = parser.parse_args()\n    args.output_dir.mkdir(parents=True, exist_ok=True)\n\n    with args.input.open(newline="", encoding="utf-8") as f:\n        source = list(csv.DictReader(f))\n    if len(source) != 532 or len({r["filename"] for r in source}) != len(source):\n        raise ValueError("expected 532 unique input filename rows")\n    primitive_columns = [c for c in source[0] if c.startswith("gate_") and c != "gate_depth"]\n    mapped_columns = {c for columns in CANONICAL_GATE_SOURCES.values() for c in columns}\n    if set(primitive_columns) != mapped_columns:\n        raise ValueError(f"primitive gate mapping does not cover source columns: "\n                         f"unmapped={sorted(set(primitive_columns) - mapped_columns)}, "\n                         f"missing={sorted(mapped_columns - set(primitive_columns))}")\n    # Independent raw-column check required by the v3 data contract. gate_depth\n    # is schedule depth and is deliberately excluded from primitive counts.\n    for row in source:\n        if _bool(row.get("counts_exact", "")):\n            raw_sum = sum(_int_exact(row, col) for col in primitive_columns)\n            unitary = _int_exact(row, "unitary_count")\n            if raw_sum != unitary:\n                raise ValueError(f"{row[\'filename\']}: raw primitive gate sum {raw_sum} != unitary_count {unitary}")\n    derived = [derive(row) for row in source]\n    with (args.output_dir / "composition_features.csv").open("w", newline="", encoding="utf-8") as f:\n        writer = csv.DictWriter(f, fieldnames=OUTPUT_COLUMNS)\n        writer.writeheader()\n        writer.writerows(derived)\n    dict_rows = dictionary_rows()\n    with (args.output_dir / "FEATURE_DICTIONARY.csv").open("w", newline="", encoding="utf-8") as f:\n        writer = csv.DictWriter(f, fieldnames=list(dict_rows[0]))\n        writer.writeheader()\n        writer.writerows(dict_rows)\n\n    counts_exact = [_bool(r.get("counts_exact", "")) for r in source]\n    depth_exact = [_bool(r.get("depth_exact", "")) for r in source]\n    exact_out = [d for d, flag in zip(derived, counts_exact) if flag]\n    positive = [d for d in exact_out if sum((d[c] or 0) for c in PROPORTION_COLUMNS) > 0]\n    zero_unitary = sum(_int_exact(r, "unitary_count") == 0 for r, flag in zip(source, counts_exact) if flag)\n    depth_ratio_rows = [d for d, flag in zip(derived, depth_exact) if flag]\n    # Meaningful implementation invariants, evaluated on data and before export.\n    if any(abs(sum(float(d[c]) for c in PROPORTION_COLUMNS) - 1.0) > 1e-12 for d in positive):\n        raise AssertionError("positive exact gate proportions do not sum to one")\n    if any(not (0.0 <= float(d["gate_type_entropy_norm"]) <= 1.0 + 1e-12) for d in positive):\n        raise AssertionError("normalized gate entropy falls outside [0, 1]")\n    if any(d["gate_type_diversity"] == 1 and abs(float(d["gate_type_entropy"])) > 1e-12 for d in positive):\n        raise AssertionError("single-type circuit must have zero gate entropy")\n    for d, flag in zip(derived, counts_exact):\n        if not flag and any(d[c] is not None for c in FEATURE_COLUMNS if not c.startswith("gate_depth_per_")):\n            raise AssertionError("inexact count row received a count-derived value")\n    for d, flag in zip(derived, depth_exact):\n        if not flag and any(d[c] is not None for c in ("gate_depth_per_qubit", "gate_depth_per_unitary")):\n            raise AssertionError("inexact depth row received a depth-derived value")\n\n    summary = {\n        "source": str(args.input),\n        "source_sha256": hashlib.sha256(args.input.read_bytes()).hexdigest(),\n        "rows": len(source), "features": len(FEATURE_COLUMNS),\n        "columns": FEATURE_COLUMNS, "join_key": "filename",\n        "coverage": {\n            "counts_exact_rows": sum(counts_exact), "counts_inexact_rows": len(source) - sum(counts_exact),\n            "positive_unitary_count_exact_rows": len(positive), "zero_unitary_count_exact_rows": zero_unitary,\n            "depth_exact_rows": sum(depth_exact), "depth_inexact_rows": len(source) - sum(depth_exact),\n            "depth_per_qubit_available": sum(d["gate_depth_per_qubit"] is not None for d in derived),\n            "depth_per_unitary_available": sum(d["gate_depth_per_unitary"] is not None for d in derived),\n        },\n        "mapping": {k: list(v) for k, v in CANONICAL_GATE_SOURCES.items()},\n        "families": {k: list(v) for k, v in FAMILIES.items()},\n        "notes": [\n            "U and u source columns are merged into one canonical u category before proportions and entropy.",\n            "Family buckets are name-based and intentionally overlap; parameter-dependent Clifford membership is never inferred.",\n            "Gate-type entropy is distinct from v3 graph degree-mass entropy.",\n            "Rows and derived columns contain no outcomes, statuses, timings, arbitrary source text, or identifiers other than filename join key.",\n            "No model fitting or importance analysis was performed.",\n        ],\n    }\n    (args.output_dir / "summary.json").write_text(json.dumps(summary, indent=2) + "\\n", encoding="utf-8")\n    print(json.dumps({"rows": len(source), "features": len(FEATURE_COLUMNS), "coverage": summary["coverage"]}, indent=2))\n\n\nif __name__ == "__main__":\n    main()\n', _adapter_module.__file__, 'exec'), _adapter_module.__dict__)
