exec(compile('"""Portable, bounded QASM-to-v4 inference features. Standard library only.\n\nThe source files beside this adapter are snapshots of the reviewed extractors.\nNo training rows, circuit identifiers, labels, or runtime observations are used.\n"""\n\nfrom __future__ import annotations\n\nimport math\nimport re\nimport time\n\nimport _qr_v5_base_extractor as base_extractor\nimport _qr_v5_composition as composition\nimport _qr_v5_extractor as extractor\nimport _qr_v5_graph_features as graph_features\nimport _qr_v5_schema as schema\nimport _qr_v5_sequence_extractor as sequence_extractor\n\n_MAX_GRAPH_QUBITS = 4096\n_MAX_GRAPH_EDGES = 200_000\n_DEFAULT_TOTAL_S = 11.0\n_INLINE_DECLARATION = re.compile(r";([ \\t]*(?:qreg|qubit)\\b)")\n\n\ndef _finite(value):\n    if value is None or isinstance(value, (bool, str)):\n        return value\n    try:\n        return value if math.isfinite(value) else None\n    except (TypeError, ValueError, OverflowError):\n        return None\n\n\ndef _graph_fields(row, prefix, n, edges):\n    values = graph_features.graph_features(n, edges)\n    row.update({prefix + key: value for key, value in values.items()\n                if prefix + key in row})\n\n\ndef _twoq_derived(row, edges, n):\n    weights = [edge[2] for edge in edges]\n    total = sum(weights)\n    if total:\n        shares = [weight / total for weight in weights]\n        row["twoq_reuse"] = total / len(weights)\n        row["twoq_top_pair_share"] = max(shares)\n        row["twoq_pair_mass_entropy"] = -sum(p * math.log2(p) for p in shares)\n        row["native_cut_per_twoq"] = row["twoq_native_max_cut"] / total\n        row["rcm_cut_per_twoq"] = row["twoq_rcm_max_cut"] / total\n    else:\n        for key in ("twoq_reuse", "twoq_top_pair_share", "twoq_pair_mass_entropy",\n                    "native_cut_per_twoq", "rcm_cut_per_twoq"):\n            row[key] = 0.0\n\n\ndef _structural_fields(row, structural, deadline):\n    n = structural.get("n_qubits")\n    row["n_qubits"] = n if isinstance(n, int) and 0 < n <= 120_000 else None\n    for flag in ("counts_exact", "graph_exact", "depth_exact"):\n        row[flag] = bool(structural.get(flag))\n    if row["counts_exact"]:\n        for key in ("unitary_count", "twoq_count", "multiq_count", "measurement_count",\n                    "reset_count", "active_qubit_layers"):\n            row[key] = structural.get(key)\n        counts = structural.get("primitive_counts") or {}\n        for name in counts:\n            key = "gate_" + name\n            if key in row:\n                row[key] = counts[name]\n        for key in row:\n            if key.startswith("gate_") and key[5:] in composition.CANONICAL_GATE_SOURCES:\n                row[key] = counts.get(key[5:], 0)\n        # The uppercase legacy U count is a distinct raw column.\n        if "gate_U" in row:\n            row["gate_U"] = counts.get("U", 0)\n        if "gate_u" in row:\n            row["gate_u"] = counts.get("u", 0)\n        if row["n_qubits"]:\n            for source, target in (("unitary_count", "unitary_per_qubit"),\n                                   ("twoq_count", "twoq_per_qubit"),\n                                   ("measurement_count", "measurement_per_qubit"),\n                                   ("reset_count", "reset_per_qubit")):\n                row[target] = row[source] / row["n_qubits"]\n            row["generic_entanglement_ratio_twoq"] = row["twoq_count"] / max(1, row["unitary_count"])\n        try:\n            comp_row = {key: "" if value is None else str(value) for key, value in row.items()}\n            comp_row["filename"] = ""\n            row.update({key: value for key, value in composition.derive(comp_row).items() if key in row})\n        except (ValueError, TypeError, ZeroDivisionError, OverflowError):\n            # A new primitive name outside the reviewed composition vocabulary\n            # must not receive a false distribution over known gates.\n            pass\n    if row["depth_exact"]:\n        for key in ("gate_depth", "twoq_depth", "critical_path_twoq_count"):\n            row[key] = structural.get(key)\n        if row["counts_exact"] and n:\n            depth, total, twoq = row["gate_depth"], row["unitary_count"], row["twoq_count"]\n            row["generic_parallelism"] = max(0, (total / depth - 1) / (n - 1)) if depth and n > 1 else 0.0\n            row["generic_liveness"] = row["active_qubit_layers"] / (n * depth) if depth else 0.0\n            row["generic_critical_depth_twoq"] = row["critical_path_twoq_count"] / twoq if twoq else 0.0\n            row["filtered_twoq_depth_fraction"] = row["twoq_depth"] / twoq if twoq else 0.0\n            row["gate_depth_per_qubit"] = depth / n\n            row["gate_depth_per_unitary"] = depth / total if total else None\n    graph_ready = False\n    if (row["graph_exact"] and n and n <= _MAX_GRAPH_QUBITS\n            and time.perf_counter() < deadline - 0.15):\n        edges = structural.get("edges")\n        twoq_edges = structural.get("twoq_edges")\n        if (isinstance(edges, list) and isinstance(twoq_edges, list)\n                and len(edges) <= _MAX_GRAPH_EDGES and len(twoq_edges) <= _MAX_GRAPH_EDGES):\n            try:\n                _graph_fields(row, "twoq_", n, twoq_edges)\n                _graph_fields(row, "interaction_pair_", n, edges)\n                _twoq_derived(row, twoq_edges, n)\n                row["generic_program_communication_twoq"] = row["twoq_density"]\n                graph_ready = True\n            except (ValueError, TypeError, KeyError, OverflowError):\n                pass\n    if row["graph_exact"] and not graph_ready:\n        row["graph_exact"] = False\n\n\ndef featurize(qasm_text: str, budget_s: float = _DEFAULT_TOTAL_S) -> dict:\n    """Return all 341 v4 numeric/quality fields, using None for unavailable data.\n\n    At most 7.5 seconds go to unordered structural extraction and at most\n    3 seconds to the ordered extension. The overall remaining budget is checked\n    before the second pass. Python callbacks inside the reviewed parsers check\n    time periodically, so the cap is cooperative rather than a hard kill.\n    """\n    row = {key: None for key in schema.COLUMNS}\n    for flag in ("counts_exact", "graph_exact", "depth_exact", "v4_sequence_exact",\n                 "v4_operand_loads_exact", "v4_parameter_coverage_exact"):\n        row[flag] = False\n    if isinstance(qasm_text, bytes):\n        qasm_text = qasm_text.decode("utf-8", "replace")\n    if not isinstance(qasm_text, str) or not qasm_text:\n        return row\n    try:\n        total_budget = min(_DEFAULT_TOTAL_S, max(0.01, float(budget_s)))\n        start = time.perf_counter()\n        deadline = start + total_budget\n        structural_budget = min(7.5, max(0.01, total_budget - 3.0))\n        structural_input = qasm_text\n        # The reviewed v3 quick declaration scan requires the declaration at\n        # line start. Preserve its exact corpus behavior on that common path,\n        # while accepting legal compact QASM with declarations after a \';\'.\n        if (len(qasm_text) <= base_extractor._DETAILED_LIMIT_CHARS\n                and base_extractor._quick_registers(qasm_text)[0] is None):\n            structural_input = _INLINE_DECLARATION.sub(r";\\n\\1", qasm_text)\n        structural = extractor.extract_features(structural_input, budget_s=structural_budget)\n        _structural_fields(row, structural, deadline)\n        remaining = deadline - time.perf_counter()\n        if remaining > 0.15:\n            extension = sequence_extractor.extract_extension(qasm_text, budget_s=min(3.0, remaining))\n            for key, value in extension.items():\n                name = "v4_" + key\n                if name in row:\n                    row[name] = value\n            if row["n_qubits"] is None and row["v4_sequence_exact"]:\n                row["n_qubits"] = row["v4_n_qubits"]\n            if not row["v4_parameter_coverage_exact"]:\n                for key in schema.MASKED_PARAMETERS:\n                    row[key] = None\n    except Exception:\n        # A malformed or unexpected source still yields a valid feature row.\n        if row["n_qubits"] is None:\n            try:\n                n, _ = base_extractor._quick_registers(qasm_text)\n                row["n_qubits"] = n if n and n <= 120_000 else None\n            except Exception:\n                pass\n    return {key: _finite(value) for key, value in row.items()}\n', _adapter_module.__file__, 'exec'), _adapter_module.__dict__)
