_m = _adapter_types.ModuleType('_qr_v5_tabular_portable')
_adapter_sys.modules['_qr_v5_tabular_portable'] = _m
exec(compile('"""Dependency-free prediction for exported tabular runtime models.\n\nThis module intentionally imports only the Python standard library so its\nfunctions can be copied into a single-file competition submission.\n"""\n\nimport math\nimport struct\n\n\ndef _float32(value):\n    """Match sklearn\'s tree and neighbor input conversion to float32."""\n    value = float(value)\n    try:\n        return struct.unpack("<f", struct.pack("<f", value))[0]\n    except OverflowError:\n        return math.copysign(math.inf, value)\n\n\ndef _tree_value(tree, row):\n    node = 0\n    left = tree["left"]\n    right = tree["right"]\n    feature = tree["feature"]\n    threshold = tree["threshold"]\n    values = tree["value"]\n    while left[node] != -1:\n        node = left[node] if _float32(row[feature[node]]) <= threshold[node] else right[node]\n    return values[node]\n\n\ndef portable_predict_log(model_dict, row):\n    """Predict one log10 runtime from a JSON-deserialized exported model.\n\n    ``row`` must be the same finite, preprocessed numeric feature vector used\n    for fitting. The caller owns preprocessing and feature order.\n    """\n    kind = model_dict["kind"]\n    expected = model_dict["n_features"]\n    if len(row) != expected:\n        raise ValueError("feature count mismatch: expected %d, got %d" % (expected, len(row)))\n    if kind == "median":\n        result = model_dict["value"]\n    elif kind in ("ridge", "censored_ridge"):\n        result = model_dict["intercept"] + sum(\n            coefficient * float(value)\n            for coefficient, value in zip(model_dict["coef"], row)\n        )\n    elif kind == "knn":\n        query = [_float32(value) for value in row]\n        distances = []\n        for index, train_row in enumerate(model_dict["X"]):\n            squared = sum((x - train_x) ** 2 for x, train_x in zip(query, train_row))\n            distances.append((math.sqrt(squared), index))\n        distances.sort(key=lambda pair: (pair[0], pair[1]))\n        neighbors = distances[: model_dict["n_neighbors"]]\n        labels = model_dict["y"]\n        weights = model_dict["sample_weight"]\n        zero = [(index, weights[index]) for distance, index in neighbors if distance == 0.0]\n        if zero:\n            denominator = sum(weight for _, weight in zero)\n            result = sum(labels[index] * weight for index, weight in zero) / denominator\n        elif model_dict["weights"] == "distance":\n            terms = [(index, weights[index] / distance) for distance, index in neighbors]\n            denominator = sum(weight for _, weight in terms)\n            result = sum(labels[index] * weight for index, weight in terms) / denominator\n        else:\n            denominator = sum(weights[index] for _, index in neighbors)\n            result = sum(labels[index] * weights[index] for _, index in neighbors) / denominator\n    elif kind == "extra_trees":\n        trees = model_dict["trees"]\n        result = sum(_tree_value(tree, row) for tree in trees) / len(trees)\n    elif kind == "boosting":\n        result = model_dict["init"] + model_dict["learning_rate"] * sum(\n            _tree_value(tree, row) for tree in model_dict["trees"]\n        )\n    else:\n        raise ValueError("unsupported model kind: %s" % kind)\n    if not math.isfinite(result):\n        raise ValueError("non-finite model prediction")\n    return float(result)\n\n\ndef portable_predict_many(model_dict, rows):\n    return [portable_predict_log(model_dict, row) for row in rows]\n', 'portable.py', 'exec'), _m.__dict__)

_m = _adapter_types.ModuleType('_qr_v5_mixture_portable')
_adapter_sys.modules['_qr_v5_mixture_portable'] = _m
exec(compile('"""Dependency-free predictor for forests exported by ``MixtureModel.to_dict``.\n\nThis file uses only the Python standard library so deployments need not install\nNumPy or scikit-learn merely to load and evaluate an exported model.\n"""\nimport struct\n\n\ndef _f32(value):\n    return struct.unpack("f", struct.pack("f", float(value)))[0]\n\n\ndef _tree_value(tree, row):\n    node = 0\n    while tree["feature"][node] >= 0:\n        feature = tree["feature"][node]\n        if _f32(row[feature]) <= tree["threshold"][node]:\n            node = tree["children_left"][node]\n        else:\n            node = tree["children_right"][node]\n    return tree["value"][node]\n\n\ndef _forest_predict(forest, row, classifier=False):\n    values = [_tree_value(tree, row) for tree in forest["estimators"]]\n    if not classifier:\n        return sum(float(v[0][0]) for v in values) / len(values)\n    n_classes = len(forest["classes"])\n    totals = [0.0] * n_classes\n    for value in values:\n        flat = [float(x) for output in value for x in output]\n        for j, probability in enumerate(flat):\n            totals[j] += probability / len(values)\n    return totals\n\n\ndef portable_predict_log(model_dict, row):\n    """Return one log-runtime prediction from a JSON-exported mixture model."""\n    x = [float(v) for v in row]\n    n_features = int(model_dict["n_features"])\n    if len(x) != n_features:\n        raise ValueError(f"row must have {n_features} features")\n    experts = model_dict["experts"]\n    gate = model_dict["gate"]\n    if experts is None or gate is None:\n        fallback = model_dict["fallback"]\n        return (float(model_dict["constant"]) if fallback is None\n                else float(_forest_predict(fallback, x)))\n    p = _forest_predict(gate, x, classifier=True)\n    full = [0.0] * len(experts)\n    for j, cls in enumerate(gate["classes"]):\n        full[int(cls)] = float(p[j])\n    predictions = [_forest_predict(expert, x) for expert in experts]\n    if model_dict["combination"] == "hard":\n        return float(predictions[max(range(len(full)), key=full.__getitem__)])\n    return float(sum(probability * prediction\n                     for probability, prediction in zip(full, predictions)))\n', 'portable.py', 'exec'), _m.__dict__)

_m = _adapter_types.ModuleType('_qr_v5_pipeline')
_adapter_sys.modules['_qr_v5_pipeline'] = _m
exec(compile('"""Only standard-library operations; included verbatim in the submission."""\nimport math\n\ndef safe_number(value):\n    try:\n        value=float(value)\n        return value if math.isfinite(value) else None\n    except (TypeError,ValueError,OverflowError):\n        if value==\'True\':return 1.\n        if value==\'False\':return 0.\n        return None\n\ndef preprocess(features, threshold, pre):\n    vals=[safe_number(features.get(n)) for n in pre[\'names\']]\n    t=safe_number(threshold) or 64.\n    vals += [math.log2(max(1.,t)),float(t==16),float(t==64),float(t==512)]\n    result=[];missing=[]\n    for j,med,center,scale in zip(pre[\'use\'],pre[\'medians\'],pre[\'centers\'],pre[\'scales\']):\n        v=vals[j];missing.append(float(v is None))\n        a=med if v is None else math.copysign(math.log1p(abs(v)),v)\n        # Guards only arithmetic extremes, not ordinary size extrapolation.\n        result.append(max(-1e6,min(1e6,(a-center)/scale)))\n    return result+missing\n\ndef availability_route(features):\n    if any(safe_number(features.get(k)) is None for k in (\'unitary_count\',\'twoq_count\')):\n        return \'qubits_only\'\n    if any(safe_number(features.get(k)) is None for k in (\'gate_depth\',\'generic_critical_depth_twoq\',\'generic_liveness\',\'generic_parallelism\')):\n        return \'counts_only\'\n    return \'main\'\n\ndef predict_pipeline(features, threshold, bundle, tabular_predict, mixture_predict=None):\n    route=availability_route(features)\n    fallback=bundle.get(\'availability_fallbacks\',{}).get(route)\n    if fallback:\n        return predict_pipeline(features,threshold,fallback,tabular_predict,mixture_predict)\n    key=str(int(threshold)) if bundle[\'separate_thresholds\'] else \'pooled\'\n    part=bundle[\'parts\'].get(key) or bundle[\'parts\'].get(\'64\') or next(iter(bundle[\'parts\'].values()))\n    x=preprocess(features,threshold,part[\'preprocessor\'])\n    m=part[\'model\']\n    if m.get(\'format\')==\'quantum-rings-gmm-moe-v1\': logp=mixture_predict(m,x)\n    else: logp=tabular_predict(m,x)\n    gate=part.get(\'timeout_gate\')\n    if gate:\n        # Gate is a regression forest fitted to 0/1 censoring indicators.\n        probability=max(0.,min(1.,tabular_predict(gate,x)))\n        if probability>=bundle[\'timeout_cutoff\']:logp=math.log10(14400.)\n    if not math.isfinite(logp):raise ValueError(\'nonfinite predictor output\')\n    # Broad numerical guard, not an assertion that large successes are impossible.\n    return 10**max(-6.,min(8.,logp))\n', 'portable_pipeline.py', 'exec'), _m.__dict__)

_PACKED_MODEL = ''
_FALLBACK_SECONDS = {'16': 1.5307986, '64': 4.1559375, '512': 91.75166269999998}

class RuntimeModel:
    """One-file model. QASM input and threshold are the only inference inputs."""
    def __init__(self):
        self.fallback_count = 0
        try:
            self._bundle = _json.loads(_zlib.decompress(_b64.b64decode(_PACKED_MODEL)))
        except Exception:
            self._bundle = None

    def featurize(self, qasm_text):
        try:
            return featurize(qasm_text, budget_s=11.0)
        except Exception:
            return {}

    def predict(self, features, threshold):
        try:
            threshold = int(threshold)
        except (TypeError, ValueError, OverflowError):
            threshold = 64
        if threshold not in (16, 64, 512):
            threshold = 64
        try:
            if not isinstance(features, dict) or self._bundle is None:
                raise ValueError('unavailable features or model')
            if not any(features.get(k) is not None for k in ('n_qubits','unitary_count','twoq_count')):
                raise ValueError('no structural information')
            value = _adapter_sys.modules['_qr_v5_pipeline'].predict_pipeline(
                features, threshold, self._bundle,
                _adapter_sys.modules['_qr_v5_tabular_portable'].portable_predict_log,
                _adapter_sys.modules['_qr_v5_mixture_portable'].portable_predict_log)
            if not _math.isfinite(value) or value <= 0:
                raise ValueError('invalid predicted duration')
            return max(1e-6, float(value))
        except Exception:
            self.fallback_count += 1
            return float(_FALLBACK_SECONDS.get(str(threshold), _FALLBACK_SECONDS['64']))
